// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // initial owner is address(0); it can transfer ownership to anyone
        vm.prank(c.owner());
        c.transferOwnership(newOwner);

        // rule: the CURRENT owner can always successfully call owned()
        vm.prank(c.owner());
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}
